// Tests only: `virtual:pwa-register/react` is generated by vite-plugin-pwa, which is off under
// Vitest. Tests that care about the update prompt override this with `vi.mock`.
export function useRegisterSW() {
  return {
    needRefresh: [false, () => {}] as const,
    offlineReady: [false, () => {}] as const,
    updateServiceWorker: () => Promise.resolve(),
  };
}
